import sys
import math
sys.setrecursionlimit(10000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Precompute GCD matrix
    gcd_ok = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if math.gcd(a[i], a[j]) > 1:
                gcd_ok[i][j] = True

    # DP tables
    # left_dp[l][r] = True if interval [l,r] can be a left child of parent at r+1
    # right_dp[l][r] = True if interval [l,r] can be a right child of parent at l-1
    left_dp = [[False]*n for _ in range(n)]
    right_dp = [[False]*n for _ in range(n)]

    # Initialize for single vertices
    for i in range(n):
        left_dp[i][i] = True
        right_dp[i][i] = True

    # Process intervals by increasing length
    for length in range(2, n+1):
        for l in range(n-length+1):
            r = l + length - 1
            # Try each possible root k in [l,r]
            for k in range(l, r+1):
                left_valid = True
                right_valid = True

                # Check left subtree [l,k-1]
                if k > l:
                    left_valid = left_dp[l][k-1]

                # Check right subtree [k+1,r]
                if k < r:
                    right_valid = right_dp[k+1][r]

                if left_valid and right_valid:
                    # This interval can be a left child of parent at r+1
                    if r+1 < n and gcd_ok[k][r+1]:
                        left_dp[l][r] = True

                    # This interval can be a right child of parent at l-1
                    if l-1 >= 0 and gcd_ok[k][l-1]:
                        right_dp[l][r] = True

    # Check if any root can form a valid tree
    possible = False
    for k in range(n):
        left_valid = True
        right_valid = True

        if k > 0:
            left_valid = left_dp[0][k-1]
        if k < n-1:
            right_valid = right_dp[k+1][n-1]

        if left_valid and right_valid:
            possible = True
            break

    print("Yes" if possible else "No")

if __name__ == "__main__":
    solve()

