import sys
sys.setrecursionlimit(300000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    main_courses = set(int(next(it)) - 1 for _ in range(k))

    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        t = int(next(it))
        indeg[i] = t
        for _ in range(t):
            dep = int(next(it)) - 1
            adj[dep].append(i)

    # BFS from main courses to find required courses
    required = [False] * n
    queue = []
    for course in main_courses:
        if not required[course]:
            required[course] = True
            queue.append(course)

    front = 0
    while front < len(queue):
        u = queue[front]
        front += 1
        for dep in adj[u]:
            if not required[dep]:
                required[dep] = True
                queue.append(dep)

    # Build subgraph of required courses
    sub_adj = [[] for _ in range(n)]
    sub_indeg = [0] * n
    for u in range(n):
        if required[u]:
            for v in adj[u]:
                if required[v]:
                    sub_adj[u].append(v)
                    sub_indeg[v] += 1

    # Topological sort on subgraph
    topo = []
    q = []
    for u in range(n):
        if required[u] and sub_indeg[u] == 0:
            q.append(u)

    front = 0
    while front < len(q):
        u = q[front]
        front += 1
        topo.append(u)
        for v in sub_adj[u]:
            sub_indeg[v] -= 1
            if sub_indeg[v] == 0:
                q.append(v)

    if len(topo) != sum(required):
        print(-1)
        return

    m = len(topo)
    print(m)
    print(' '.join(str(x + 1) for x in topo))

if __name__ == "__main__":
    solve()

