import sys
sys.setrecursionlimit(300000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    main_courses = set()
    for _ in range(k):
        main_courses.add(int(next(it)) - 1)  # 0-index

    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        t = int(next(it))
        for _ in range(t):
            dep = int(next(it)) - 1  # 0-index
            adj[dep].append(i)
            indeg[i] += 1

    # Topological sort with BFS (Kahn's algorithm)
    from collections import deque
    q = deque()
    for i in range(n):
        if indeg[i] == 0:
            q.append(i)

    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    if len(order) != n:
        print(-1)
        return

    # Mark courses that are required (main courses and their prerequisites)
    required = [False] * n
    # Process in topological order to propagate requirements
    for u in order:
        if u in main_courses:
            required[u] = True
        # If any successor is required, this course is required
        for v in adj[u]:
            if required[v]:
                required[u] = True
                break

    # Now propagate backwards: if a course is required, all its prerequisites are required
    # Process in reverse topological order
    for u in reversed(order):
        if required[u]:
            for v in adj[u]:
                required[v] = True

    # Collect required courses in topological order
    result = []
    for u in order:
        if required[u]:
            result.append(u + 1)  # back to 1-index

    print(len(result))
    if result:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()

