import sys
import heapq

input = sys.stdin.read
def solve():
    data = input().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    flights = []
    for _ in range(m):
        d = int(next(it))
        f = int(next(it))
        t = int(next(it))
        c = int(next(it))
        flights.append((d, f, t, c))
    flights.sort()
    max_day = 10**6 + 2
    arrival_costs = [{} for _ in range(max_day + 2)]
    departure_costs = [{} for _ in range(max_day + 2)]
    for d, f, t, c in flights:
        if f != 0:
            arrival_costs[d][f] = min(arrival_costs[d].get(f, float('inf')), c)
        else:
            departure_costs[d][t] = min(departure_costs[d].get(t, float('inf')), c)
    prefix_min = [float('inf')] * (max_day + 2)
    best_arrival = {}
    total_cost = 0
    for day in range(1, max_day + 1):
        for city, cost in arrival_costs[day].items():
            if city not in best_arrival:
                best_arrival[city] = cost
                total_cost += cost
            elif cost < best_arrival[city]:
                total_cost -= best_arrival[city]
                best_arrival[city] = cost
                total_cost += cost
        if len(best_arrival) == n:
            prefix_min[day] = total_cost
        else:
            prefix_min[day] = float('inf')
    suffix_min = [float('inf')] * (max_day + 2)
    best_departure = {}
    total_cost = 0
    for day in range(max_day, 0, -1):
        for city, cost in departure_costs[day].items():
            if city not in best_departure:
                best_departure[city] = cost
                total_cost += cost
            elif cost < best_departure[city]:
                total_cost -= best_departure[city]
                best_departure[city] = cost
                total_cost += cost
        if len(best_departure) == n:
            suffix_min[day] = total_cost
        else:
            suffix_min[day] = float('inf')
    ans = float('inf')
    for start_day in range(1, max_day - k):
        end_day = start_day + k + 1
        if prefix_min[start_day - 1] != float('inf') and suffix_min[end_day] != float('inf'):
            ans = min(ans, prefix_min[start_day - 1] + suffix_min[end_day])
    if ans == float('inf'):
        print(-1)
    else:
        print(ans)

if __name__ == "__main__":
    solve()

