def main():
    data = input().split()
    n = int(data[0])
    sx = int(data[1])
    sy = int(data[2])

    west = east = south = north = 0
    idx = 3
    for _ in range(n):
        x = int(data[idx]); y = int(data[idx+1])
        idx += 2
        if x < sx:
            west += 1
        if x > sx:
            east += 1
        if y < sy:
            south += 1
        if y > sy:
            north += 1

    max_count = max(west, east, south, north)

    if max_count == west:
        px, py = sx - 1, sy
    elif max_count == east:
        px, py = sx + 1, sy
    elif max_count == south:
        px, py = sx, sy - 1
    else:
        px, py = sx, sy + 1

    # Ensure coordinates are within [0, 1e9] as per problem constraints
    px = max(0, min(px, 10**9))
    py = max(0, min(py, 10**9))

    print(max_count)
    print(px, py)

if __name__ == "__main__":
    main()

