import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    ts = int(data[0])
    tf = int(data[1])
    t = int(data[2])
    n = int(data[3])

    arrivals = []
    if n > 0:
        arrivals = list(map(int, data[4:4+n]))

    # If no visitors, Vasya can come at ts
    if n == 0:
        print(ts)
        return

    # Simulate queue processing
    current_time = ts  # when receptionist starts
    best_time = -1
    min_wait = float('inf')

    # Check arrival at time 0
    if ts >= 0:
        # Find first visitor arrival time >= 0
        # Since arrivals are non-decreasing and positive, first arrival is arrivals[0]
        first_arrival = arrivals[0]
        if first_arrival > 0:
            # Vasya can come at 0 and be served immediately if receptionist starts at ts >= 0
            # But need to check if he would be served before tf
            if ts + t <= tf:
                wait_time = max(0, ts - 0)  # actually 0 if he comes at 0 and served at ts
                if wait_time < min_wait:
                    min_wait = wait_time
                    best_time = 0
        else:
            # first_arrival == 0 (though problem says positive, but handle edge)
            # Vasya would yield to visitors arriving at same time
            # So he'd be after them in queue
            pass

    # Check gaps between visitor arrivals
    for i in range(n):
        # Try arriving just before this visitor
        candidate = arrivals[i] - 1
        if candidate >= 0:
            # Simulate queue up to this candidate
            sim_time = ts
            for j in range(i):
                # Process visitor j
                if sim_time < arrivals[j]:
                    sim_time = arrivals[j]
                # Check if can serve before tf
                if sim_time + t > tf:
                    # Cannot serve visitor j, break
                    break
                sim_time += t
            else:
                # Processed all previous visitors
                # Now check if candidate can be served
                if sim_time < candidate:
                    sim_time = candidate
                if sim_time + t <= tf:
                    wait_time = sim_time - candidate
                    if wait_time < min_wait:
                        min_wait = wait_time
                        best_time = candidate

        # Try arriving at same time as this visitor (but yields, so effectively after)
        candidate = arrivals[i]
        # Simulate queue including this visitor
        sim_time = ts
        for j in range(i+1):  # include current visitor
            if sim_time < arrivals[j]:
                sim_time = arrivals[j]
            if sim_time + t > tf:
                break
            sim_time += t
        else:
            # Vasya arrives at candidate, yields to visitors at same time
            # So he'd be served at sim_time (after processing all including current)
            if sim_time + t <= tf:
                wait_time = sim_time - candidate
                if wait_time < min_wait:
                    min_wait = wait_time
                    best_time = candidate

    # Check after last visitor
    # Simulate processing all visitors
    sim_time = ts
    for i in range(n):
        if sim_time < arrivals[i]:
            sim_time = arrivals[i]
        if sim_time + t > tf:
            # Cannot serve all, break
            break
        sim_time += t
    else:
        # Processed all visitors
        # Vasya can come at sim_time (when receptionist becomes free)
        if sim_time < tf:
            wait_time = 0
            if wait_time < min_wait:
                min_wait = wait_time
                best_time = sim_time
        # Also try times between last arrival and sim_time
        if n > 0:
            last_arrival = arrivals[-1]
            for candidate in range(last_arrival + 1, sim_time):
                if candidate >= 0:
                    # Vasya would be served at sim_time since he comes after last visitor
                    if sim_time + t <= tf:
                        wait_time = sim_time - candidate
                        if wait_time < min_wait:
                            min_wait = wait_time
                            best_time = candidate

    # If no candidate found (shouldn't happen per problem guarantee), fallback
    if best_time == -1:
        # Try coming at ts
        if ts + t <= tf:
            best_time = ts
        else:
            # Should not happen
            best_time = 0

    print(best_time)

