import sys

def can_seat(groups, X):
    """Check if all groups can be seated with width X."""
    # Create a list of group sizes with their counts
    group_list = []
    for size, count in enumerate(groups, start=1):
        group_list.extend([size] * count)

    # Sort groups by size descending for better packing
    group_list.sort(reverse=True)

    # Try to seat groups using backtracking
    rows = []

    def backtrack(idx):
        if idx == len(group_list):
            return True

        group_size = group_list[idx]

        # Try placing in existing rows
        for i in range(len(rows)):
            if rows[i] + group_size + 1 <= X:  # +1 for mandatory gap
                rows[i] += group_size + 1
                if backtrack(idx + 1):
                    return True
                rows[i] -= group_size + 1

        # Try placing in new row
        if group_size <= X:
            rows.append(group_size)
            if backtrack(idx + 1):
                return True
            rows.pop()

        return False

    return backtrack(0)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    groups = list(map(int, data[1:1+n]))

    total_people = sum((i+1) * groups[i] for i in range(n))

    # Search for minimum X from 1 to 12
    for X in range(1, 13):
        if can_seat(groups, X):
            print(X)
            return

    print("impossible")

if __name__ == "__main__":
    solve()

