import sys
from collections import deque

# Directions: up, down, left, right
DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return "IMPOSSIBLE"

    R, C = map(int, data[0].split())
    maze = data[1:]

    # Find Joe's starting position and initial fire positions
    joe_start = None
    fire_queue = deque()
    fire_time = [[-1] * C for _ in range(R)]

    for i in range(R):
        for j in range(C):
            if maze[i][j] == 'J':
                joe_start = (i, j)
            elif maze[i][j] == 'F':
                fire_queue.append((i, j))
                fire_time[i][j] = 0

    # BFS to compute fire spread times
    while fire_queue:
        x, y = fire_queue.popleft()
        for dx, dy in DIRS:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C:
                if maze[nx][ny] != '#' and fire_time[nx][ny] == -1:
                    fire_time[nx][ny] = fire_time[x][y] + 1
                    fire_queue.append((nx, ny))

    # BFS for Joe's escape
    joe_queue = deque()
    joe_visited = [[False] * C for _ in range(R)]
    joe_start_x, joe_start_y = joe_start
    joe_queue.append((joe_start_x, joe_start_y, 0))
    joe_visited[joe_start_x][joe_start_y] = True

    while joe_queue:
        x, y, time = joe_queue.popleft()

