import sys
from collections import deque

# Directions: up, down, left, right
DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return "IMPOSSIBLE"

    R, C = map(int, data[0].split())
    maze = data[1:]

    # Find Joe's starting position and initial fire positions
    joe_start = None
    fire_queue = deque()
    fire_time = [[-1] * C for _ in range(R)]

    for i in range(R):
        for j in range(C):
            if maze[i][j] == 'J':
                joe_start = (i, j)
            elif maze[i][j] == 'F':
                fire_queue.append((i, j))
                fire_time[i][j] = 0

    # BFS to compute fire spread times
    while fire_queue:
        x, y = fire_queue.popleft()
        for dx, dy in DIRS:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C:
                if maze[nx][ny] != '#' and fire_time[nx][ny] == -1:
                    fire_time[nx][ny] = fire_time[x][y] + 1
                    fire_queue.append((nx, ny))

    # BFS for Joe's escape
    joe_queue = deque()
    joe_visited = [[False] * C for _ in range(R)]
    joe_start_x, joe_start_y = joe_start
    joe_queue.append((joe_start_x, joe_start_y, 0))
    joe_visited[joe_start_x][joe_start_y] = True

    while joe_queue:
        x, y, time = joe_queue.popleft()

        # Check if Joe is at the border (escape condition)
        if x == 0 or x == R-1 or y == 0 or y == C-1:
            return str(time + 1)  # +1 because we count the minute to exit

        for dx, dy in DIRS:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C:
                # Check if cell is passable and not visited
                if maze[nx][ny] != '#' and not joe_visited[nx][ny]:
                    # Check if fire reaches this cell at the same time or earlier than Joe
                    fire_reach_time = fire_time[nx][ny]
                    if fire_reach_time == -1 or fire_reach_time > time + 1:
                        joe_visited[nx][ny] = True
                        joe_queue.append((nx, ny, time + 1))

    return "IMPOSSIBLE"

if __name__ == "__main__":
    print(solve())

