import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    idx = 1

    # Dictionary to store needed boxes at each size 2^k
    needed = {}
    max_k = 0

    for _ in range(n):
        k = int(data[idx]); idx += 1
        a = int(data[idx]); idx += 1
        needed[k] = a
        if k > max_k:
            max_k = k

    # Combine boxes upward
    p = max_k
    while True:
        if p not in needed:
            needed[p] = 0

        # Combine boxes at level p
        if needed[p] > 1:
            # Each group of 4 boxes of size 2^p can be packed into one box of size 2^{p+1}
            carry = needed[p] // 4
            remainder = needed[p] % 4

            if carry > 0:
                if p + 1 not in needed:
                    needed[p + 1] = 0
                needed[p + 1] += carry

                # Update max_k if we go beyond current max
                if p + 1 > max_k:
                    max_k = p + 1

            needed[p] = remainder

            # If we created boxes at higher level, continue combining from there
            if carry > 0:
                p = max_k
                continue

        # Move to next level if current level has 0 or 1 box
        if needed[p] <= 1:
            if p == max_k:
                # Check if we need to create a new box at higher level
                if needed[p] == 1 and p > 0:
                    # A single box at level p needs a container at level p+1
                    needed[p + 1] = needed.get(p + 1, 0) + 1
                    needed[p] = 0
                    max_k = p + 1
                    p = max_k
                    continue
                else:
                    break
            else:
                p += 1
                continue

        p += 1

    # Find the smallest p such that we have exactly 1 box at that level
    # or the highest level with any boxes
    result = max_k
    while result > 0 and needed.get(result, 0) == 0:
        result -= 1

    # If we have more than 1 box at the highest level, we need to go one level higher
    if needed.get(result, 0) > 1:
        result += 1

    print(result)

if __name__ == "__main__":
    solve()

