import sys
import heapq

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    A = [list(map(int, input().split())) for _ in range(N)]

    # Check basic properties
    for i in range(N):
        if A[i][i] != 0:
            print(-1)
            return
        for j in range(N):
            if i != j and A[i][j] != A[j][i]:
                print(-1)
                return
            if i != j and A[i][j] <= 0:
                print(-1)
                return

    # Check triangle inequality
    for i in range(N):
        for j in range(N):
            for k in range(N):
                if A[i][j] > A[i][k] + A[k][j]:
                    print(-1)
                    return

    # Find all valid direct edges
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            # Check if edge (i,j) is necessary
            necessary = True
            for k in range(N):
                if k != i and k != j and A[i][j] == A[i][k] + A[k][j]:
                    necessary = False
                    break
            if necessary:
                edges.append((A[i][j], i, j))

    # Build graph with all necessary edges
    adj = [[] for _ in range(N)]
    total_length = 0
    for w, u, v in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
        total_length += w

    # Verify all distances match using Dijkstra
    for s in range(N):
        dist = [float('inf')] * N
        dist[s] = 0
        pq = [(0, s)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

        for t in range(N):
            if dist[t] != A[s][t]:
                print(-1)
                return

    print(total_length)

if __name__ == "__main__":
    solve()

