import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    canisters = list(map(int, data[1:1+n]))
    canisters.sort()

    # Early impossible check: any canister exceeds its balloon's capacity
    for i in range(n):
        if canisters[i] > i + 1:
            print("impossible")
            return

    # Binary search for maximum minimum fraction f
    lo, hi = 0.0, 1.0
    for _ in range(60):  # enough for 1e-6 precision
        mid = (lo + hi) / 2
        feasible = True
        for i in range(n):
            # Check if canister fits within scaled capacity
            if canisters[i] > mid * (i + 1):
                feasible = False
                break
        if feasible:
            lo = mid
        else:
            hi = mid

    print(f"{lo:.10f}")

if __name__ == "__main__":
