import sys

def parse_note(note_str):
    """Parse a note string into pitch and duration."""
    pitch = note_str[0]
    duration = 1
    if len(note_str) > 1 and note_str[1].isdigit():
        duration = int(note_str[1])
    return pitch, duration

def pitch_to_line(pitch):
    """Map pitch letter to staff line index (0-13)."""
    # Staff lines from top to bottom: G, F, E, D, C, B, A, g, f, e, d, c, b, a
    mapping = {
        'G': 0, 'F': 1, 'E': 2, 'D': 3, 'C': 4, 'B': 5, 'A': 6,
        'g': 7, 'f': 8, 'e': 9, 'd': 10, 'c': 11, 'b': 12, 'a': 13
    }
    return mapping[pitch]

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    notes = data[1].strip().split()

    # Validate input length
    if len(notes) != n:
        # If mismatch, use actual number of notes
        n = len(notes)

    # Initialize staff lines
    staff_lines = [
        'G:', 'F:', 'E:', 'D:', 'C:', 'B:', 'A:',
        'g:', 'f:', 'e:', 'd:', 'c:', 'b:', 'a:'
    ]

    # Create empty staff with proper initial formatting
    staff = [line + ' ' for line in staff_lines]

    # Process each note
    for i, note_str in enumerate(notes):
        pitch, duration = parse_note(note_str)
        line_idx = pitch_to_line(pitch)

        # Add separator before note (except first note)
        if i > 0:
            for j in range(len(staff)):
                staff[j] += ' '

        # Add asterisks for the note
        asterisks = '*' * duration
        for j in range(len(staff)):
            if j == line_idx:
                staff[j] += asterisks
            else:
                # Add spaces for other lines
                staff[j] += ' ' * duration

    # Convert spaces to dashes on staff lines that should be dashed
    dashed_lines = {1, 3, 5, 7, 9, 13}  # F, D, B, g, e, a lines
    for idx in dashed_lines:
        line = list(staff[idx])
        for i in range(len(line)):
            if line[i] == ' ' and i >= 2:  # Skip the label part
                line[i] = '-'
        staff[idx] = ''.join(line)

    # Print the staff
    for line in staff:
        print(line.rstrip())

if __name__ == "__main__":
    main()

