def can_be_obfuscated(s):
    """Check if string s can be result of Kostya's obfuscation."""
    mapping = {}  # identifier -> obfuscated letter
    next_letter = ord('a')

    i = 0
    while i < len(s):
        # Find the next identifier (sequence of same letters)
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        identifier = s[i:j]

        # Check if this identifier has been seen before
        if identifier in mapping:
            # Must map to the same letter as before
            if mapping[identifier] != s[i]:
                return False
        else:
            # New identifier - assign next available letter
            if next_letter > ord('z'):
                return False  # More than 26 unique identifiers
            if chr(next_letter) != s[i]:
                return False  # Letter doesn't match obfuscation order
            mapping[identifier] = s[i]
            next_letter += 1

        i = j

    return True

if __name__ == "__main__":
    s = input().strip()
    print("YES" if can_be_obfuscated(s) else "NO")

