def count_divisible(a: int, b: int, x: int) -> int:
    """Return count of integers in [a, b] divisible by x."""
    # Count from 0 to b minus count from 0 to a-1
    count_to_b = b // x
    count_to_a_minus_one = (a - 1) // x if a > 0 else -1  # Special case for a=0

    if a == 0:
        # 0 is divisible by any positive x, so include it
        return count_to_b + 1
    else:
        return count_to_b - count_to_a_minus_one

