import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    k = int(data[0])

    # For k=1, impossible because a cube has 0 neighbors
    if k == 1:
        print(-1)
        return

    # For k=2, we can use a checkerboard pattern
    if k == 2:
        print("bb")
        print("ww")
        print()
        print("bb")
        print("ww")
        return

    # For k >= 3, we can construct a 3D pattern where each cube has exactly 2 neighbors of same color
    # We'll create alternating layers of two patterns
    pattern1 = []
    pattern2 = []

    # Create two k×k patterns that alternate
    for i in range(k):
        row1 = []
        row2 = []
        for j in range(k):
            # Pattern1: checkerboard starting with 'b' at (0,0)
            if (i + j) % 2 == 0:
                row1.append('b')
            else:
                row1.append('w')
            # Pattern2: opposite of pattern1
            if (i + j) % 2 == 0:
                row2.append('w')
            else:
                row2.append('b')
        pattern1.append(''.join(row1))
        pattern2.append(''.join(row2))

    # Output k layers alternating between pattern1 and pattern2
    for layer in range(k):
        if layer % 2 == 0:
            for row in pattern1:
                print(row)
        else:
            for row in pattern2:
                print(row)
        if layer != k - 1:
            print()

if __name__ == "__main__":
    solve()

