import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    k = int(data[0])

    # For k=1, impossible: a single cube has 0 neighbors, can't have exactly 2 same-colored neighbors
    if k == 1:
        print(-1)
        return

    # For k=2, we can use the pattern from the example
    if k == 2:
        print("bb")
        print("ww")
        print()
        print("bb")
        print("ww")
        return

    # For k >= 3, we can construct a 3D pattern where each cube has exactly 2 neighbors of same color
    # Approach: Create alternating layers of black and white stripes
    # Each layer: alternating rows of all black and all white
    # This ensures each cube has exactly 2 same-colored neighbors (above and below in adjacent layers)

    # Build the cube layer by layer
    for layer in range(k):
        for row in range(k):
            # Alternate pattern: even rows black, odd rows white in each layer
            # But we also alternate layers to ensure proper neighbor counts
            if (layer % 2 == 0):
                # Even layers: even rows black, odd rows white
                if row % 2 == 0:
                    print('b' * k)
                else:
                    print('w' * k)
            else:
                # Odd layers: even rows white, odd rows black (inverted)
                if row % 2 == 0:
                    print('w' * k)
                else:
                    print('b' * k)
        # Print empty line between layers (optional, as per problem statement)
        if layer != k-1:
            print()

if __name__ == "__main__":
    solve()

