import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    positions = [chr(ord('a') + i) for i in range(n)]
    pos_to_idx = {pos: i for i, pos in enumerate(positions)}

    # Parse options
    options = []
    for i in range(n):
        m = int(next(it))
        opts = []
        for _ in range(m):
            s = next(it)
            mask = 0
            for ch in s:
                mask |= 1 << pos_to_idx[ch]
            opts.append(mask)
        options.append(opts)

    # dp[mask][pos] = minimal max rounds to reach any position in mask from pos
    # Initialize with INF
    INF = 10**9
    dp = [[INF] * n for _ in range(1 << n)]

    # Base case: if target mask contains current position, 0 rounds
    for mask in range(1 << n):
        for pos in range(n):
            if mask & (1 << pos):
                dp[mask][pos] = 0

    # BFS-like propagation: process masks in increasing order of bits
    # We need to propagate backwards: from larger masks to smaller masks
    # Actually we need to compute for each mask and position
    # We'll iterate until convergence
    changed = True
    while changed:
        changed = False
        # For each mask
        for mask in range(1 << n):
            # For each position
            for pos in range(n):
                if dp[mask][pos] == 0:
                    continue

                # Alice chooses an option
                best = INF
                for opt_mask in options[pos]:
                    # Bob chooses the worst (maximum) next position
                    worst = 0
                    # For each possible next position in this option
                    for next_pos in range(n):
                        if opt_mask & (1 << next_pos):
                            worst = max(worst, dp[mask][next_pos] + 1)
                    best = min(best, worst)

                if best < dp[mask][pos]:
                    dp[mask][pos] = best
                    changed = True

    # Prepare output
    output_lines = []
    for start_idx in range(n):
        line = []
        for target_idx in range(n):
            mask = 1 << target_idx
            val = dp[mask][start_idx]
            if val >= INF // 2:
                line.append("-1")
            else:
                line.append(str(val))
        output_lines.append(" ".join(line))

    sys.stdout.write("\n".join(output_lines))

if __name__ == "__main__":
    solve()

