import sys

def is_tolerable(s, p):
    """Check if string s is tolerable."""
    n = len(s)
    # Check each character is within first p letters
    max_char = chr(ord('a') + p - 1)
    for ch in s:
        if ch > max_char:
            return False

    # Check for palindromes of length 2 or more
    for i in range(n):
        for length in [2, 3]:  # Only need to check lengths 2 and 3
            j = i + length - 1
            if j >= n:
                break
            # Check if substring s[i:j+1] is palindrome
            if s[i] == s[j] and (length == 2 or s[i+1] == s[j-1]):
                return False
    return True

def next_char(ch, p):
    """Return next character within first p letters, or None if at max."""
    max_char = chr(ord('a') + p - 1)
    if ch == max_char:
        return None
    return chr(ord(ch) + 1)

def find_next_tolerable(s, p):
    """Find lexicographically next tolerable string of same length."""
    n = len(s)
    s_list = list(s)

    # Try to increment from the end
    for i in range(n-1, -1, -1):
        original = s_list[i]
        next_ch = next_char(original, p)
        while next_ch is not None:
            s_list[i] = next_ch
            # Fill the rest with smallest possible characters
            for j in range(i+1, n):
                # Try 'a' first, then increment if needed
                candidate = 'a'
                s_list[j] = candidate
                # Adjust if creates palindrome
                while True:
                    # Check palindrome conditions
                    ok = True
                    # Check length 2 palindrome ending at j
                    if j >= 1 and s_list[j] == s_list[j-1]:
                        ok = False
                    # Check length 3 palindrome ending at j
                    if j >= 2 and s_list[j] == s_list[j-2]:
                        ok = False
                    if ok:
                        break
                    # Try next character
                    next_candidate = next_char(candidate, p)
                    if next_candidate is None:
                        ok = False
                        break
                    candidate = next_candidate
                    s_list[j] = candidate
                if not ok:
                    break
            else:
                # All positions filled successfully
                if is_tolerable(''.join(s_list), p):
                    return ''.join(s_list)

            # Try next character at position i
            next_ch = next_char(next_ch, p)

        # Reset current position to original and continue
        s_list[i] = original

    return "NO"

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    p = int(data[1])
    s = data[2]

    result = find_next_tolerable(s, p)
    print(result)

if __name__ == "__main__":
