import sys

def read_board():
    """Read the ASCII chessboard from stdin."""
    board = []
    for _ in range(8):
        line = sys.stdin.readline().strip()
        # Skip the border lines (starting with '+')
        if line.startswith('+'):
            continue
        # Extract the piece positions from the row
        # Each cell is 4 chars: '|', char1, char2, char3
        row_pieces = []
        for i in range(0, len(line), 4):
            cell = line[i+1:i+4]  # Skip the leading '|'
            # The middle character is the piece or empty
            piece_char = cell[1]
            if piece_char in '.:':
                row_pieces.append('.')
            else:
                row_pieces.append(piece_char)
        board.append(row_pieces)
    return board

def get_position(row, col):
    """Convert board indices to chess notation."""
    # Row: 0 (top) -> 8, 7 (bottom) -> 1
    # Col: 0 (left) -> 'a', 7 (right) -> 'h'
    chess_row = str(8 - row)
    chess_col = chr(ord('a') + col)
    return chess_col + chess_row

def solve():
    board = read_board()
    white_pieces = {'K': [], 'Q': [], 'R': [], 'B': [], 'N': [], 'P': []}
    black_pieces = {'K': [], 'Q': [], 'R': [], 'B': [], 'N': [], 'P': []}

    # Collect pieces
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if piece == '.':
                continue
            pos = get_position(r, c)
            if piece.isupper():
                white_pieces[piece].append(pos)
            else:
                black_pieces[piece.upper()].append(pos)

    # Sort pieces according to the rules
    order = ['K', 'Q', 'R', 'B', 'N', 'P']

    def sort_key_white(pos):
        # For white: smaller row first, then smaller column
        return (-int(pos[1]), pos[0])  # Row descending (8->1), col ascending

    def sort_key_black(pos):
        # For black: larger row first, then smaller column
        return (int(pos[1]), pos[0])   # Row ascending (1->8), col ascending

    white_result = []
    black_result = []

    for piece_type in order:
        white_list = sorted(white_pieces[piece_type], key=sort_key_white)
        black_list = sorted(black_pieces[piece_type], key=sort_key_black)

        for pos in white_list:
            if piece_type == 'P':
                white_result.append(pos)
            else:
                white_result.append(piece_type + pos)

        for pos in black_list:
            if piece_type == 'P':
                black_result.append(pos)
            else:
                black_result.append(piece_type + pos)

    print(f"White: {','.join(white_result)}")
    print(f"Black: {','.join(black_result)}")

if __name__ == "__main__":
    solve()

