import sys

# Helper function to convert grid to tuple for memoization
def grid_to_tuple(grid):
    return tuple(tuple(row) for row in grid)

# Check if a move is valid
def is_valid_move(r, c, dr, dc, k, grid):
    nr, nc = r + dr, c + dc
    if nr < 0 or nr >= 2 or nc < 0 or nc >= 2*k + 1:
        return False
    # Vertical moves only allowed in leftmost, rightmost, or centermost columns
    if dr != 0 and c not in (0, k, 2*k):
        return False
    return True

# Solve a single test case
def solve_case(k, grid):
    # Find empty cell
    er, ec = None, None
    for r in range(2):
        for c in range(2*k + 1):
            if grid[r][c] == 'E':
                er, ec = r, c
                break
        if er is not None:
            break

    # BFS to find solution
    from collections import deque
    target_grid = [[0]*(2*k + 1) for _ in range(2)]
    for c in range(2*k + 1):
        target_grid[0][c] = str(c + 1)  # organs 1 to 2k+1
    for c in range(2*k + 1):
        if c < 2*k:
            target_grid[1][c] = str(2*k + 2 + c)  # organs 2k+2 to 4k+1
        else:
            target_grid[1][c] = 'E'  # last cell is empty

    # Convert target to tuple
    target_state = grid_to_tuple(target_grid)

    # BFS initialization
    start_state = grid_to_tuple(grid)
    if start_state == target_state:
        return True, ""  # Already solved

    queue = deque()
    queue.append((er, ec, start_state, ""))
    visited = {start_state}

    # Directions: u, d, l, r
    dirs = [(-1, 0, 'u'), (1, 0, 'd'), (0, -1, 'l'), (0, 1, 'r')]

    while queue:
        r, c, state, moves = queue.popleft()
        grid_list = [list(row) for row in state]

        for dr, dc, move_char in dirs:
            if is_valid_move(r, c, dr, dc, k, grid_list):
                nr, nc = r + dr, c + dc
                # Swap empty with organ
                new_grid = [row[:] for row in grid_list]
                new_grid[r][c], new_grid[nr][nc] = new_grid[nr][nc], new_grid[r][c]
                new_state = grid_to_tuple(new_grid)

                if new_state == target_state:
                    return True, moves + move_char

                if new_state not in visited:
                    visited.add(new_state)
                    # Limit BFS depth to avoid explosion (k <= 15, grid has 4k+2 cells)
                    if len(moves) < 1000:  # Reasonable limit for BFS
                        queue.append((nr, nc, new_state, moves + move_char))

    return False, ""

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    t = int(input_data[0])
    idx = 1
    results = []

    for _ in range(t):
        k = int(input_data[idx]); idx += 1
        grid = []
        for _ in range(2):
            row = input_data[idx:idx + 2*k + 1]
            idx += 2*k + 1
            grid.append(row)

        possible, moves = solve_case(k, grid)

        if possible:
            # Use shortcuts to compress output
            # Simple compression: use R for 'r' repeated
            if moves:
                # Create a simple shortcut if moves are long
                if len(moves) > 10:
                    # Use R for 'r' and L for 'l' as shortcuts
                    compressed = moves.replace('r', 'R').replace('l', 'L')
                    results.append("SURGERY COMPLETE")
                    results.append(compressed)
                    results.append("R r")
                    results.append("L l")
                else:
                    results.append("SURGERY COMPLETE")
                    results.append(moves)
                    results.append("R r")  # Dummy shortcuts
                    results.append("L l")
            else:
                results.append("SURGERY COMPLETE")
                results.append("")
                results.append("R r")
                results.append("L l")
            results.append("DONE")
        else:
            results.append("SURGERY FAILED")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()

