import sys
from collections import deque

# Hopcroft-Karp algorithm for bipartite matching
def hopcroft_karp(adj, n_left, n_right):
    INF = 10**9
    pair_u = [-1] * n_left
    pair_v = [-1] * n_right
    dist = [0] * n_left

    def bfs():
        q = deque()
        for u in range(n_left):
            if pair_u[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF
        dist_null = INF
        while q:
            u = q.popleft()
            if dist[u] < dist_null:
                for v in adj[u]:
                    if pair_v[v] == -1:
                        dist_null = dist[u] + 1
                    elif dist[pair_v[v]] == INF:
                        dist[pair_v[v]] = dist[u] + 1
                        q.append(pair_v[v])
        return dist_null != INF

    def dfs(u):
        for v in adj[u]:
            if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = INF
        return False

    matching = 0
    while bfs():
        for u in range(n_left):
            if pair_u[u] == -1 and dfs(u):
                matching += 1
    return matching

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    x_to_id = {}
    y_to_id = {}
    x_ids = []
    y_ids = []

    # Map coordinates to indices for bipartite graph
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))
        if x not in x_to_id:
            x_to_id[x] = len(x_to_id)
        if y not in y_to_id:
            y_to_id[y] = len(y_to_id)
        x_ids.append(x_to_id[x])
        y_ids.append(y_to_id[y])

    n_left = len(x_to_id)  # X coordinates
    n_right = len(y_to_id)  # Y coordinates

    # Build adjacency list: X nodes to Y nodes
    adj = [[] for _ in range(n_left)]
    for i in range(n):
        u = x_ids[i]
        v = y_ids[i]
        adj[u].append(v)

    # Remove duplicates in adjacency lists
    for u in range(n_left):
        adj[u] = list(set(adj[u]))

    max_matching = hopcroft_karp(adj, n_left, n_right)

    # If maximum matching equals number of points, Slavko wins; otherwise Mirko wins
    if max_matching == n:
        print("Slavko")
    else:
        print("Mirko")

if __name__ == "__main__":
    main()

