import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:1+n]))

    # Map values to indices for O(1) lookup
    pos = [0] * (n + 1)
    for i, val in enumerate(p):
        pos[val] = i

    # Fenwick tree for counting elements in range
    class Fenwick:
        def __init__(self, n):
            self.n = n
            self.bit = [0] * (n + 1)
        def add(self, idx, delta):
            i = idx + 1
            while i <= self.n:
                self.bit[i] += delta
                i += i & -i
        def sum(self, idx):
            res = 0
            i = idx + 1
            while i > 0:
                res += self.bit[i]
                i -= i & -i
            return res
        def range_sum(self, l, r):
            if l > r:
                return 0
            return self.sum(r) - self.sum(l - 1)

    bit = Fenwick(n)
    ans = n  # All length-1 subarrays are scary

    # Process each possible median value
    for median in range(1, n + 1):
        median_pos = pos[median]
        bit.add(median_pos, 1)

        # Try subarrays where median is at left boundary
        # We need exactly (len-1)//2 elements < median to the right
        for length in range(3, n + 1, 2):  # Odd lengths only
            needed_smaller = (length - 1) // 2
            # Right boundary position
            right_pos = median_pos + length - 1
            if right_pos >= n:
                break
            # Count how many elements < median in [median_pos+1, right_pos]
            smaller_count = bit.range_sum(median_pos + 1, right_pos)
            if smaller_count == needed_smaller:
                ans += 1

        # Try subarrays where median is at right boundary
        for length in range(3, n + 1, 2):
            needed_smaller = (length - 1) // 2
            left_pos = median_pos - length + 1
            if left_pos < 0:
                break
            smaller_count = bit.range_sum(left_pos, median_pos - 1)
            if smaller_count == needed_smaller:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

