import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    H, W, K = map(int, data[:3])
    grid = data[3:]

    # Convert grid to bitmask representation for rows
    row_masks = [0] * H
    for i in range(H):
        mask = 0
        for j in range(W):
            if grid[i][j] == '#':
                mask |= (1 << j)
        row_masks[i] = mask

    total_choices = 0

    # Iterate over all subsets of rows (2^H possibilities, H ≤ 6)
    for row_mask in range(1 << H):
        # Count black cells in each column that are NOT in selected rows
        col_black_counts = [0] * W

        for j in range(W):
            count = 0
            for i in range(H):
                # If row i is NOT selected and cell is black
                if not (row_mask >> i) & 1 and (row_masks[i] >> j) & 1:
                    count += 1
            col_black_counts[j] = count

        # Now we need to count subsets of columns where sum of col_black_counts = K
        # Use DP for subset sum
        max_sum = sum(col_black_counts)
        if max_sum < K:
            continue

        # DP[j][s] = number of ways to achieve sum s using first j columns
        # We can optimize space using 1D array
        dp = [0] * (max_sum + 1)
        dp[0] = 1  # empty subset

        for count in col_black_counts:
            # Update dp backwards to avoid reusing same column multiple times
            for s in range(max_sum, count - 1, -1):
                dp[s] += dp[s - count]

        if K <= max_sum:
            total_choices += dp[K]

    print(total_choices)

if __name__ == "__main__":
    solve()

