import sys

input = sys.stdin.readline

def solve():
    n = int(input().strip())
    a = list(map(int, input().split()))

    # If all elements are already distinct
    if len(set(a)) == n:
        print(0)
        return

    # Precompute last occurrence of each value
    last_occurrence = {}
    for i in range(n):
        last_occurrence[a[i]] = i

    min_remove = n  # Initialize with worst case (remove entire array)

    # Try all possible left boundaries
    for l in range(n):
        seen = set()
        r = l - 1  # Start with empty segment

        # Try to extend r to the right as much as possible
        # while keeping elements from l to r distinct
        for r_candidate in range(l, n):
            if a[r_candidate] in seen:
                break
            seen.add(a[r_candidate])
            r = r_candidate

        # Now check if the remaining elements (outside [l, r]) are distinct
        remaining_seen = set()
        valid = True

        for i in range(n):
            if l <= i <= r:
                continue  # This element is removed
            if a[i] in remaining_seen:
                valid = False
                break
            remaining_seen.add(a[i])

        if valid:
            min_remove = min(min_remove, r - l + 1)

    print(min_remove)

if __name__ == "__main__":
    solve()

