import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m, n, t = map(int, data)

    # Map t to complexity function
    if t == 1:  # O(n!)
        fact = 1
        for i in range(1, n + 1):
            if fact > m // i:  # Early overflow detection
                print("TLE")
                return
            fact *= i
        print("AC" if fact <= m else "TLE")

    elif t == 2:  # O(2^n)
        # For n >= 30, 2^n > 1e9 typically
        if n >= 30:
            print("TLE")
        else:
            val = 1 << n  # 2^n
            print("AC" if val <= m else "TLE")

    elif t == 3:  # O(n^4)
        # Avoid overflow by checking n^2 first
        if n > 1000:  # 1000^4 = 1e12 > 1e9
            print("TLE")
        else:
            val = n * n * n * n
            print("AC" if val <= m else "TLE")

    elif t == 4:  # O(n^3)
        if n > 1000:  # 1000^3 = 1e9
            print("TLE")
        else:
            val = n * n * n
            print("AC" if val <= m else "TLE")

    elif t == 5:  # O(n^2)
        val = n * n
        print("AC" if val <= m else "TLE")

    elif t == 6:  # O(n log2 n)
        if n == 0:
            print("AC")
        else:
            # Use integer arithmetic for log2
            log_val = n.bit_length() - 1  # floor(log2(n))
            # Ceil(log2(n)) = log_val + 1 if n is not power of 2
            if n & (n - 1):
                log_val += 1
            val = n * log_val
            print("AC" if val <= m else "TLE")

    elif t == 7:  # O(n)
        print("AC" if n <= m else "TLE")

if __name__ == "__main__":
    solve()

