import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    # Count frequency of each character
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - ord('a')] += 1

    # Check if any character appears at least twice or if n == 1
    possible = False
    for count in freq:
        if count >= 2:
            possible = True
            break

    # Special case: if n == 1, always possible (already single color)
    if n == 1:
        possible = True

    print("Yes" if possible else "No")

if __name__ == "__main__":
    solve()

