import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a = int(data[0])
    b = int(data[1])
    s = data[2]

    # Compute net displacement after one full command
    dx = 0
    dy = 0
    for ch in s:
        if ch == 'U':
            dy += 1
        elif ch == 'D':
            dy -= 1
        elif ch == 'R':
            dx += 1
        elif ch == 'L':
            dx -= 1

    # Check if (a,b) can be reached after some number of repetitions
    x = 0
    y = 0
    # First, check if (a,b) is (0,0) initially
    if a == 0 and b == 0:
        print("Yes")
        return

    # Check each prefix position
    for ch in s:
        if ch == 'U':
            y += 1
        elif ch == 'D':
            y -= 1
        elif ch == 'R':
            x += 1
        elif ch == 'L':
            x -= 1

        # After this move, we are at (x,y).
        # We need to check if we can reach (a,b) by adding some integer k repetitions of the full command displacement (dx,dy)
        # So we need: x + k*dx = a  and  y + k*dy = b for some non-negative integer k.
        # This gives: k*dx = a - x, k*dy = b - y.
        # If dx == 0 and dy == 0, then we must have x == a and y == b exactly.
        if dx == 0 and dy == 0:
            if x == a and y == b:
                print("Yes")
                return
        else:
            # Check if k is a non-negative integer that satisfies both equations.
            kx = None
            ky = None
            if dx != 0:
                if (a - x) % dx == 0:
                    kx = (a - x) // dx
                else:
                    continue
            if dy != 0:
                if (b - y) % dy == 0:
                    ky = (b - y) // dy
                else:
                    continue

            # If both dx and dy are zero, we already handled above.
            # Now we need to check if there exists a common k >= 0.
            if dx == 0:
                # Then we require x == a, and ky must be >= 0.
                if x == a and ky is not None and ky >= 0:
                    print("Yes")
                    return
            elif dy == 0:
                if y == b and kx is not None and kx >= 0:
                    print("Yes")
                    return
            else:
                # Both dx and dy are non-zero.
                if kx is not None and ky is not None and kx == ky and kx >= 0:
                    print("Yes")
                    return

    print("No")

if __name__ == "__main__":
    solve()

