def solve():
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequencies of each number
    freq = {}
    for x in a:
        freq[x] = freq.get(x, 0) + 1

    # Precompute powers of two up to 2^31 (since a_i <= 1e9, sum <= 2*1e9 < 2^31)
    powers = [1 << d for d in range(32)]  # 2^0 to 2^31

    # Sort unique numbers for processing
    unique_nums = sorted(freq.keys())

    # For each number, check if it can pair with another (including itself if count > 1)
    # We'll mark numbers that are "good" (have a partner)
    good_nums = set()

    for x in unique_nums:
        # Check all powers of two
        for p in powers:
            y = p - x
            if y < 1:
                continue
            if y == x:
                # Need at least 2 copies of x
                if freq[x] >= 2:
                    good_nums.add(x)
                    break
            else:
                if y in freq:
                    good_nums.add(x)
                    break

    # Count numbers that are NOT good
    bad_count = 0
    for x in unique_nums:
        if x not in good_nums:
            bad_count += freq[x]

    print(bad_count)

