import sys
import math

MOD = 998244353

def cross(ax, ay, bx, by):
    return ax * by - ay * bx

def orientation(a, b, c):
    return cross(b[0]-a[0], b[1]-a[1], c[0]-b[0], c[1]-b[1])

def is_convex(poly):
    if len(poly) < 3:
        return False
    n = len(poly)
    sign = 0
    for i in range(n):
        cur = orientation(poly[i], poly[(i+1)%n], poly[(i+2)%n])
        if cur != 0:
            if sign == 0:
                sign = 1 if cur > 0 else -1
            elif (sign > 0 and cur < 0) or (sign < 0 and cur > 0):
                return False
    return True

def point_in_convex_hull(p, hull):
    if len(hull) < 3:
        return False
    n = len(hull)
    for i in range(n):
        if cross(hull[(i+1)%n][0]-hull[i][0], hull[(i+1)%n][1]-hull[i][1], p[0]-hull[i][0], p[1]-hull[i][1]) < 0:
            return False
    return True

def main():
    input = sys.stdin.readline
    N = int(input().strip())
    points = []
    for _ in range(N):
        x, y = map(int, input().split())
        points.append((x, y))

    pow2 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    ans = 0
    for mask in range(1, 1 << N):
        subset = []
        for i in range(N):
            if mask & (1 << i):
                subset.append(points[i])
        if not is_convex(subset):
            continue

        inside_count = 0
        for i in range(N):
            if point_in_convex_hull(points[i], subset):
                inside_count += 1

        score = pow2[inside_count - len(subset)]
        ans = (ans + score) % MOD

    print(ans)

if __name__ == "__main__":
    main()

