# Kosaraju's algorithm for SCC
class SCC:
    def __init__(self, n, edges):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.rev_adj = [[] for _ in range(n)]
        for u, v in edges:
            self.adj[u].append(v)
            self.rev_adj[v].append(u)
        self.visited = [False] * n
        self.order = []
        self.comp = [-1] * n
        self.comp_cnt = 0

    def dfs1(self, u):
        self.visited[u] = True
        for v in self.adj[u]:
            if not self.visited[v]:
                self.dfs1(v)
        self.order.append(u)

    def dfs2(self, u, label):
        self.comp[u] = label
        for v in self.rev_adj[u]:
            if self.comp[v] == -1:
                self.dfs2(v, label)

    def get_scc(self):
        for i in range(self.n):
            if not self.visited[i]:
                self.dfs1(i)
        for u in reversed(self.order):
            if self.comp[u] == -1:
                self.dfs2(u, self.comp_cnt)
                self.comp_cnt += 1
        return self.comp, self.comp_cnt

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))

    # Find SCCs
    scc = SCC(n, edges)
    comp, comp_cnt = scc.get_scc()

    # Count indegree/outdegree of SCCs
    indeg = [0] * comp_cnt
    outdeg = [0] * comp_cnt
    for u, v in edges:
        cu = comp[u]
        cv = comp[v]
        if cu != cv:
            outdeg[cu] += 1
            indeg[cv] += 1

    # Count SCCs with zero indegree/outdegree
    zero_indeg = sum(1 for d in indeg if d == 0)
    zero_outdeg = sum(1 for d in outdeg if d == 0)

    # If there is only one SCC, answer is 0
    if comp_cnt == 1:
        print(0)
    else:
        print(max(zero_indeg, zero_outdeg))

if __name__ == "__main__":
    main()

