import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    R = data[0]
    C = data[1]
    n = len(R)
    m = len(C)

    # Check feasibility: sum of row parities mod 2 must equal sum of column parities mod 2
    if (sum(int(ch) for ch in R) % 2) != (sum(int(ch) for ch in C) % 2):
        print(-1)
        return

    # Initialize matrix with all ones
    matrix = [[1] * m for _ in range(n)]

    # Adjust to match row parities
    for i in range(n):
        row_parity = int(R[i])
        current_parity = m % 2  # Since all cells are 1 initially
        if current_parity != row_parity:
            # Flip one cell in this row to adjust parity
            # Choose the rightmost column to minimize binary value
            matrix[i][m-1] = 0

    # Adjust to match column parities
    for j in range(m):
        col_parity = int(C[j])
        current_parity = sum(matrix[i][j] for i in range(n)) % 2
        if current_parity != col_parity:
            # Need to flip one cell in this column
            # Choose the bottommost row to minimize binary value
            # But avoid flipping a cell that would break row parity
            found = False
            for i in range(n-1, -1, -1):
                if matrix[i][j] == 1:
                    # Check if flipping this cell would break row parity
                    row_sum = sum(matrix[i])
                    if (row_sum - 1) % 2 == int(R[i]):
                        matrix[i][j] = 0
                        found = True
                        break
            if not found:
                # If no suitable cell found, try flipping a 0 to 1
                for i in range(n-1, -1, -1):
                    if matrix[i][j] == 0:
                        row_sum = sum(matrix[i])
                        if (row_sum + 1) % 2 == int(R[i]):
                            matrix[i][j] = 1
                            found = True
                            break
            if not found:
                print(-1)
                return

    # Final verification
    for i in range(n):
        if sum(matrix[i]) % 2 != int(R[i]):
            print(-1)
            return
    for j in range(m):
        if sum(matrix[i][j] for i in range(n)) % 2 != int(C[j]):
            print(-1)
            return

    # Output the matrix
    for row in matrix:
        print(''.join(str(x) for x in row))

if __name__ == "__main__":
    solve()

