def evaluate_expression(expr):
    """Evaluate expression with bug: treats all numbers as 8-bit unsigned and wraps around."""
    # Split by '+' and '-' while keeping operators
    parts = []
    current = ''
    for ch in expr:
        if ch in '+-':
