import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]

    max_outside_len = 0
    inside_count = 0

    i = 0
    in_parentheses = False

    while i < n:
        if s[i] == '(':
            in_parentheses = True
            i += 1
        elif s[i] == ')':
            in_parentheses = False
            i += 1
        elif s[i] == '_':
            i += 1
        else:
            # Start of a word
            start = i
            while i < n and s[i].isalpha():
                i += 1
            word_len = i - start

            if in_parentheses:
                inside_count += 1
            else:
                max_outside_len = max(max_outside_len, word_len)

    print(f"{max_outside_len} {inside_count}")

if __name__ == "__main__":
    solve()

