import sys
import math

EPS = 1e-9

def orientation(p, q, r):
    """Returns 0 if collinear, 1 if clockwise, 2 if counterclockwise"""
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if abs(val) < EPS:
        return 0
    return 1 if val > 0 else 2

def on_segment(p, q, r):
    """Check if point q lies on segment pr"""
    return (min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and
            min(p[1], r[1]) <= q[1] <= max(p[1], r[1]))

def point_in_triangle(p, a, b, c):
    """Check if point p is inside triangle abc (including border)"""
    # Check if on vertices
    if p == a or p == b or p == c:
        return True

    # Check if on edges
    if orientation(a, b, p) == 0 and on_segment(a, p, b):
        return True
    if orientation(b, c, p) == 0 and on_segment(b, p, c):
        return True
    if orientation(c, a, p) == 0 and on_segment(c, p, a):
        return True

    # Check if strictly inside using barycentric coordinates
    def sign(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])

    d1 = sign(p, a, b)
    d2 = sign(p, b, c)
    d3 = sign(p, c, a)

    has_neg = (d1 < -EPS) or (d2 < -EPS) or (d3 < -EPS)
    has_pos = (d1 > EPS) or (d2 > EPS) or (d3 > EPS)

    return not (has_neg and has_pos)

def is_valid_triangle(a, b, c):
    """Check if triangle is non-degenerate (no three collinear)"""
    return orientation(a, b, c) != 0

