import sys

def is_sorted(arr, n):
    """Check if array is sorted in non-decreasing or non-increasing order."""
    non_dec = all(arr[i] <= arr[i+1] for i in range(n-1))
    non_inc = all(arr[i] >= arr[i+1] for i in range(n-1))
    return non_dec or non_inc

def check_swap(arr, i, j):
    """Check if swapping positions i and j makes array unsorted."""
    # Swap elements
    arr[i], arr[j] = arr[j], arr[i]
    result = not is_sorted(arr, len(arr))
    # Swap back
    arr[i], arr[j] = arr[j], arr[i]
    return result

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Edge cases
    if n <= 2:
        print(-1)
        return

    # Check if already unsorted
    if not is_sorted(arr, n):
        # Find first two distinct positions
        for i in range(n):
            for j in range(i+1, n):
                if arr[i] != arr[j]:
                    print(f"{i+1} {j+1}")
                    return
        print(-1)
        return

    # Array is sorted, find candidate pairs
    # Try swapping first two distinct elements
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] != arr[j]:
                if check_swap(arr, i, j):
                    print(f"{i+1} {j+1}")
                    return
                # If first distinct pair doesn't work, try last distinct pair
                # Find last distinct pair
                for k in range(n-1, -1, -1):
                    for l in range(k-1, -1, -1):
                        if arr[k] != arr[l]:
                            if check_swap(arr, l, k):
                                print(f"{l+1} {k+1}")
                                return
                print(-1)
                return

    # All elements are equal
    print(-1)

if __name__ == "__main__":
    main()

