import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = map(int, data)

    # If n equals m, no moves needed
    if n == m:
        print(0)
        return

    # Check if m is divisible by n
    if m % n != 0:
        print(-1)
        return

    quotient = m // n
    moves = 0

    # Repeatedly divide by 2 and 3 while possible
    while quotient % 2 == 0:
        quotient //= 2
        moves += 1
    while quotient % 3 == 0:
        quotient //= 3
        moves += 1

    # If quotient becomes 1, transformation is possible
    if quotient == 1:
        print(moves)
    else:
        print(-1)

if __name__ == "__main__":
    solve()

