import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    r, c = map(int, data[0].split())
    grid = [list(row.strip()) for row in data[1:1+r]]

    visited = [[False] * c for _ in range(r)]

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_r, start_c):
        """BFS from a land cell, exploring connected L and C cells.
           Returns True if at least one L is found (so it's an island)."""
        queue = deque()
        queue.append((start_r, start_c))
        visited[start_r][start_c] = True
        has_land = False

        while queue:
            cr, cc = queue.popleft()
            if grid[cr][cc] == 'L':
                has_land = True

            for dr, dc in dirs:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < r and 0 <= nc < c and not visited[nr][nc]:
                    if grid[nr][nc] == 'L' or grid[nr][nc] == 'C':
                        visited[nr][nc] = True
                        queue.append((nr, nc))
        return has_land

    islands = 0
    for i in range(r):
        for j in range(c):
            if not visited[i][j] and grid[i][j] == 'L':
                if bfs(i, j):
                    islands += 1

    # After processing all L-connected components, handle remaining C cells
    # They can all be water (since not connected to any L), so they don't form islands
    print(islands)

if __name__ == "__main__":
    solve()

