import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    d = int(data[1])
    s = data[2]

    # DP array: dp[i] = min jumps to reach position i (1-indexed)
    dp = [float('inf')] * (n + 1)
    dp[1] = 0  # start at position 1

    for i in range(1, n + 1):
        if s[i-1] == '1' and dp[i] != float('inf'):
            # try all possible jumps from i
            for jump in range(1, d + 1):
                next_pos = i + jump
                if next_pos <= n and s[next_pos-1] == '1':
                    dp[next_pos] = min(dp[next_pos], dp[i] + 1)

    result = dp[n]
    if result == float('inf'):
        print(-1)
    else:
        print(result)

if __name__ == "__main__":
    solve()

