import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    m = int(next(it))
    a = int(next(it))
    votes = [0] * (n + 1)
    last_vote = [-1] * (n + 1)
    for j in range(1, a + 1):
        g = int(next(it))
        votes[g] += 1
        last_vote[g] = j
    remaining = m - a
    result = [0] * (n + 1)
    for i in range(1, n + 1):
        current_votes = votes[i]
        current_last = last_vote[i]
        if current_votes == 0:
            if remaining == 0:
                result[i] = 3
            else:
                max_possible = remaining
                if max_possible > 0:
                    temp_votes = votes[:]
                    temp_last = last_vote[:]
                    temp_votes[i] = max_possible
                    temp_last[i] = m
                    candidates = [(temp_votes[j], -temp_last[j], j) for j in range(1, n + 1)]
                    candidates.sort(reverse=True)
                    rank = 1
                    for idx, (v, neg_l, cand) in enumerate(candidates):
                        if cand == i:
                            if rank <= k and v > 0:
                                result[i] = 2
                            else:
                                result[i] = 3
                            break
                        rank += 1
                else:
                    result[i] = 3
            continue
        best_rank = n + 1
        worst_rank = 0
        for add_self in range(remaining + 1):
            for distribute in range(remaining - add_self + 1):
                temp_votes = votes[:]
                temp_last = last_vote[:]
                temp_votes[i] += add_self
                if add_self > 0:
                    temp_last[i] = m
                other_votes = remaining - add_self
                if distribute > 0:
                    max_other = max((temp_votes[j] for j in range(1, n + 1) if j != i), default=0)
                    for _ in range(distribute):
                        for j in range(1, n + 1):
                            if j != i and temp_votes[j] == max_other:
                                temp_votes[j] += 1
                                temp_last[j] = m
                                break
                candidates = [(temp_votes[j], -temp_last[j], j) for j in range(1, n + 1)]
                candidates.sort(reverse=True)
                rank = 1
                for idx, (v, neg_l, cand) in enumerate(candidates):
                    if cand == i:
                        if v == 0:
                            rank = n + 1
                        best_rank = min(best_rank, rank)
                        worst_rank = max(worst_rank, rank)
                        break
                    rank += 1
        if best_rank <= k:
            if worst_rank <= k:
                result[i] = 1
            else:
                result[i] = 2
        else:
            result[i] = 3
    print(' '.join(str(result[i]) for i in range(1, n + 1)))

if __name__ == "__main__":
    solve()

