import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequencies of each weight
    freq = {}
    for w in a:
        freq[w] = freq.get(w, 0) + 1

    # If all weights are identical, we can determine all of them
    if len(freq) == 1:
        print(n)
        return

    # DP for counting ways to achieve (k, m)
    # dp[k][m] = number of ways to select exactly k weights with total mass m
    max_sum = sum(a)
    dp = [[0] * (max_sum + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Process each weight with its frequency
    for weight, count in freq.items():
        # Process in reverse to avoid reusing the same weight multiple times in one combination
        for k in range(n, -1, -1):
            for m in range(max_sum, -1, -1):
                if dp[k][m] == 0:
                    continue
                # Add t copies of this weight
                for t in range(1, count + 1):
                    if k + t <= n and m + t * weight <= max_sum:
                        dp[k + t][m + t * weight] += dp[k][m]
                        # Cap at 2 to avoid overflow (we only care about 0, 1, or >1)
                        if dp[k + t][m + t * weight] > 2:
                            dp[k + t][m + t * weight] = 2

    ans = 0
    # Try each possible query (k, m)
    for k in range(1, n + 1):
        for m in range(1, max_sum + 1):
            if dp[k][m] != 1:
                continue
            # Check if the complement also has exactly one way
            remaining_k = n - k
            remaining_m = max_sum - m
            if remaining_k == 0:
                # All weights selected, we know all
                ans = max(ans, n)
                continue
            if dp[remaining_k][remaining_m] == 1:
                # Both selected and remaining sets are uniquely determined
                # Count how many distinct weights we can identify
                # We can identify all weights in the smaller uniquely determined set
                identified = min(k, remaining_k)
                ans = max(ans, identified)

    # Minimum answer is 1 (we can always identify at least one weight)
    print(max(ans, 1))

if __name__ == "__main__":
    solve()

