import sys

def compute_beauty(s, n):
    """Compute maximum beauty achievable for string s with n turns."""
    length = len(s)

    # Count frequency of each character
    from collections import Counter
    freq = Counter(s)
    max_freq = max(freq.values())

    # Case 1: n is small, we can increase max_freq directly
    if max_freq + n <= length:
        return max_freq + n

    # Case 2: n is large enough to potentially reach full length
    # First, calculate how many turns needed to make all characters same
    changes_needed = length - max_freq

    if n >= changes_needed:
        leftover = n - changes_needed
        # If leftover is even, we can waste turns by swapping between two characters
        # If leftover is odd and length > 1, we can waste all but one turn,
        # then we're forced to change one character, reducing beauty by 1
        if leftover % 2 == 0:
            return length
        else:
            # Special case: length == 1
            if length == 1:
                # With odd leftover, the single character must change, beauty becomes 0
                return 0
            else:
                # We can waste all but one turn, then forced change reduces beauty by 1
                return length - 1
    else:
        # Not enough turns to make all characters same
        return max_freq + n

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ribbons = data[1:4]

    beauties = []
    for ribbon in ribbons:
        beauties.append(compute_beauty(ribbon, n))

    max_beauty = max(beauties)
    winners = []
    names = ["Kuro", "Shiro", "Katie"]

    for i, beauty in enumerate(beauties):
        if beauty == max_beauty:
            winners.append(names[i])

    if len(winners) > 1:
        print("Draw")
    else:
        print(winners[0])

if __name__ == "__main__":
    solve()

