import sys
sys.setrecursionlimit(200000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    S = int(next(it))
    E = int(next(it))
    C = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(S)]
    for _ in range(C):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)

    # Read enemies
    enemies = set()
    for _ in range(E):
        enemies.add(int(next(it)))

    # Find SCCs using Kosaraju's algorithm
    visited = [False] * S
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    # Transpose graph
    adj_rev = [[] for _ in range(S)]
    for u in range(S):
        for v in adj[u]:
            adj_rev[v].append(u)

    comp = [-1] * S
    comp_cnt = 0

    def dfs2(u, cid):
        comp[u] = cid
        for v in adj_rev[u]:
            if comp[v] == -1:
                dfs2(v, cid)

    # First pass
    for u in range(S):
        if not visited[u]:
            dfs1(u)

    # Second pass
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, comp_cnt)
            comp_cnt += 1

    # Build condensation graph
    comp_adj = [set() for _ in range(comp_cnt)]
    comp_enemy = [False] * comp_cnt

    for u in range(S):
        cu = comp[u]
        if u in enemies:
            comp_enemy[cu] = True
        for v in adj[u]:
            cv = comp[v]
            if cu != cv:
                comp_adj[cu].add(cv)

    # Find components with no incoming edges (sources)
    indegree = [0] * comp_cnt
    for u in range(comp_cnt):
        for v in comp_adj[u]:
            indegree[v] += 1

    # Count non-enemy source components
    result = 0
    for u in range(comp_cnt):
        if indegree[u] == 0 and not comp_enemy[u]:
            result += 1

    print(result)

if __name__ == "__main__":
    solve()

