import sys
sys.setrecursionlimit(200000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    S = int(next(it))
    E = int(next(it))
    C = int(next(it))

    adj = [[] for _ in range(S)]
    rev_adj = [[] for _ in range(S)]
    for _ in range(C):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        rev_adj[v].append(u)

    enemies = set()
    for _ in range(E):
        enemies.add(int(next(it)))

    # Kosaraju's algorithm
    visited = [False] * S
    order = []

    def dfs1(u):
        stack = [u]
        while stack:
            v = stack.pop()
            if visited[v]:
                continue
            visited[v] = True
            stack.append(v)
            for w in adj[v]:
                if not visited[w]:
                    stack.append(w)
            # Mark to process children first
            if stack and stack[-1] == v:
                order.append(v)
                stack.pop()

    for i in range(S):
        if not visited[i]:
            dfs1(i)

    comp_id = [-1] * S
    comp_enemy = []

    def dfs2(u, cid):
        stack = [u]
        while stack:
            v = stack.pop()
            if comp_id[v] != -1:
                continue
            comp_id[v] = cid
            for w in rev_adj[v]:
                if comp_id[w] == -1:
                    stack.append(w)

    cid = 0
    for u in reversed(order):
        if comp_id[u] == -1:
            dfs2(u, cid)
            cid += 1

    # Determine enemy components
    enemy_comp = [False] * cid
    for e in enemies:
        enemy_comp[comp_id[e]] = True

    # Count indegree in condensation graph
    indeg = [0] * cid
    for u in range(S):
        cu = comp_id[u]
        if enemy_comp[cu]:
            continue
        for v in adj[u]:
            cv = comp_id[v]
            if cu != cv and not enemy_comp[cv]:
                indeg[cv] += 1

    # Count SCCs with indegree 0 and not enemy
    result = 0
    for i in range(cid):
        if not enemy_comp[i] and indeg[i] == 0:
            result += 1

    print(result)

if __name__ == "__main__":
    solve()

