def is_diverse(s: str) -> bool:
    """Check if a string is diverse."""
    # Convert characters to their positions in the alphabet (0-based)
    positions = [ord(c) - ord('a') for c in s]

    # Check for duplicates using set
    if len(set(positions)) != len(positions):
        return False

    # Check if positions form a contiguous segment
    min_pos = min(positions)
    max_pos = max(positions)

    # The range should be exactly (max_pos - min_pos + 1) and equal to length
    return (max_pos - min_pos + 1) == len(positions)

def main() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    n = int(data[0])
    results = []

    for i in range(1, n + 1):
        s = data[i].strip()
        if is_diverse(s):
            results.append("Yes")
        else:
            results.append("No")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()

