import sys

def manhattan_distance(p1, p2):
    """Return Manhattan distance between two points."""
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def can_pair_with_max_distance(students, tutors, max_dist):
    """Check if a perfect matching exists where all distances ≤ max_dist."""
    n = len(students)
    # Build adjacency list: student i can be matched with tutor j if distance ≤ max_dist
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if manhattan_distance(students[i], tutors[j]) <= max_dist:
                adj[i].append(j)

    # Maximum bipartite matching using DFS (Kuhn's algorithm)
    match_tutor = [-1] * n  # which student is matched to tutor j

    def dfs(student, visited):
        for tutor in adj[student]:
            if not visited[tutor]:
                visited[tutor] = True
                if match_tutor[tutor] == -1 or dfs(match_tutor[tutor], visited):
                    match_tutor[tutor] = student
                    return True
        return False

    matching = 0
    for i in range(n):
        visited = [False] * n
        if dfs(i, visited):
            matching += 1
    return matching == n

