import sys
import math

MOD = 10**9 + 7

def sieve_spf(limit):
    """Sieve for smallest prime factors up to limit"""
    spf = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def factorize(x, spf):
    """Factorize x using SPF, return dictionary of prime->exponent"""
    factors = {}
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        factors[p] = factors.get(p, 0) + cnt
    return factors

def mod_pow(a, b, mod):
    """Fast exponentiation modulo mod"""
    res = 1
    while b:
        if b & 1:
            res = (res * a) % mod
        a = (a * a) % mod
        b >>= 1
    return res

def mod_inv(a, mod):
    """Modular inverse using Fermat's little theorem"""
    return mod_pow(a, mod - 2, mod)

def precompute_fact_inv(max_k, mod):
    """Precompute factorials and inverse factorials up to max_k"""
    fact = [1] * (max_k + 1)
    inv_fact = [1] * (max_k + 1)
    for i in range(1, max_k + 1):
        fact[i] = (fact[i - 1] * i) % mod
    inv_fact[max_k] = mod_inv(fact[max_k], mod)
    for i in range(max_k - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % mod
    return fact, inv_fact

def stars_and_bars(n, k, fact, inv_fact, mod):
    """Number of ways to distribute k identical items into n distinct boxes"""
    if k == 0:
        return 1
    # C(n + k - 1, k)
    numerator = fact[n + k - 1]
    denominator = (inv_fact[k] * inv_fact[n - 1]) % mod
    return (numerator * denominator) % mod

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # Compute m and its prime factorization
    m = 1
    for val in a:
        m *= val

    # Find maximum value for SPF sieve
    max_val = max(a)
    spf = sieve_spf(max_val)

    # Combine factorizations of all a_i
    total_factors = {}
    for val in a:
        factors = factorize(val, spf)
        for p, exp in factors.items():
            total_factors[p] = total_factors.get(p, 0) + exp

    # Determine maximum exponent for factorial precomputation
    max_exponent = 0
    for exp in total_factors.values():
        max_exponent = max(max_exponent, exp)
    max_k = n + max_exponent  # Upper bound for combinations

    # Precompute factorials and inverse factorials
    fact, inv_fact = precompute_fact_inv(max_k, MOD)

    # Compute answer using stars and bars for each prime
    ans = 1
    for exp in total_factors.values():
        ways = stars_and_bars(n, exp, fact, inv_fact, MOD)
        ans = (ans * ways) % MOD

    print(ans)

if __name__ == "__main__":
    main()

