import math

MOD = 10**9 + 7

def factorize(x):
    """Return prime factorization of x as dict {prime: exponent}"""
    factors = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

def nCr(n, r, fact, inv_fact):
    """Compute n choose r modulo MOD using precomputed factorials"""
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

