import sys

MOD = 0

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, p = map(int, data)
    global MOD
    MOD = p

    # Precompute all valid masks for a single row
    masks = []
    for mask in range(1 << n):
        valid = True
        # Check that no two obstacles are adjacent horizontally
        for i in range(n - 1):
            if (mask >> i) & 1 and (mask >> (i + 1)) & 1:
                valid = False
                break
        if valid:
            masks.append(mask)

    # Precompute compatibility between masks of consecutive rows
    compat = {}
    for mask1 in masks:
        compat[mask1] = []
        for mask2 in masks:
            # Check vertical adjacency
            if mask1 & mask2:
                continue
            # Check 2x2 subgrids: for each i, ensure at least one obstacle in positions
            # (i, row1), (i+1, row1), (i, row2), (i+1, row2)
            ok = True
            for i in range(n - 1):
                subgrid_mask = ((mask1 >> i) & 1) | ((mask1 >> (i + 1)) & 1) | ((mask2 >> i) & 1) | ((mask2 >> (i + 1)) & 1)
                if subgrid_mask == 0:
                    ok = False
                    break
            if ok:
                compat[mask1].append(mask2)

    # DP over columns (rows in the problem are columns here due to n <= 25, m up to 1000)
    # dp[col][mask] = number of ways to fill up to column 'col' with mask 'mask' in current column
    dp_prev = [0] * (1 << n)
    dp_curr = [0] * (1 << n)

    # Initialize first column
    for mask in masks:
        dp_prev[mask] = 1

    for col in range(1, m):
        dp_curr = [0] * (1 << n)
        for mask1 in masks:
            if dp_prev[mask1] == 0:
                continue
            for mask2 in compat[mask1]:
                dp_curr[mask2] = (dp_curr[mask2] + dp_prev[mask1]) % MOD
        dp_prev, dp_curr = dp_curr, dp_prev

    # Sum over all masks in the last column
    ans = sum(dp_prev[mask] for mask in masks) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

