import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Map each value to its first and last occurrence indices
    first_occurrence = {}
    last_occurrence = {}
    for i, val in enumerate(a):
        if val not in first_occurrence:
            first_occurrence[val] = i
        last_occurrence[val] = i

    # Merge intervals for values that appear multiple times
    intervals = []
    for val in first_occurrence:
        if first_occurrence[val] != last_occurrence[val]:
            intervals.append((first_occurrence[val], last_occurrence[val]))

    # Sort intervals by start position
    intervals.sort()

    # Merge overlapping intervals
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    # Count segments where b can increase
    # Each merged interval forces b to stay constant within it
    # Between intervals, b can either stay same or increase by 1
    segments = 0
    current_end = -1
    for start, end in merged:
        if start > current_end:
            segments += 1
        current_end = max(current_end, end)

    # If no intervals, we have n-1 positions where b can increase
    if not merged:
        segments = n - 1
    else:
        # Count gaps between merged intervals and before/after
        segments = 0
        prev_end = -1
        for start, end in merged:
            if start > prev_end + 1:
                segments += 1
            prev_end = max(prev_end, end)
        if prev_end < n - 1:
            segments += 1

    # Number of renumerations = 2^segments mod MOD
    # Because at each segment we have 2 choices: increase or not
    ans = pow(2, segments, MOD)
    print(ans)

if __name__ == "__main__":
    solve()

