import sys

def extend_name(Y, P):
    """Return the extended name according to Apaxian rules."""
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Rule 3: Y ends with "ex"
    if Y.endswith('ex'):
        return Y + P

    # Rule 1: Y ends with 'e'
    if Y[-1] == 'e':
        return Y + 'x' + P

    # Rule 2: Y ends with other vowel (a, i, o, u)
    if Y[-1] in vowels:
        return Y[:-1] + 'ex' + P

    # Default case: Y ends with consonant
    return Y + 'ex' + P

