import sys

def solve():
    input = sys.stdin.readline
    N, C = map(int, input().split())
    D = [list(map(int, input().split())) for _ in range(C)]
    grid = [list(map(int, input().split())) for _ in range(N)]

    # Count how many cells of each original color are in each modulo-3 group
    cnt = [[0] * C for _ in range(3)]
    for i in range(N):
        for j in range(N):
            group = (i + j) % 3
            color = grid[i][j] - 1  # 0-indexed
            cnt[group][color] += 1

    # Precompute cost for each group to be painted with each target color
    cost = [[0] * C for _ in range(3)]
    for g in range(3):
        for target in range(C):
            total = 0
            for orig in range(C):
                total += cnt[g][orig] * D[orig][target]
            cost[g][target] = total

    # Try all triples of distinct colors for the three groups
    ans = float('inf')
    for c0 in range(C):
        for c1 in range(C):
            if c1 == c0:
                continue
            for c2 in range(C):
                if c2 == c0 or c2 == c1:
                    continue
                total_cost = cost[0][c0] + cost[1][c1] + cost[2][c2]
                if total_cost < ans:
                    ans = total_cost

    print(ans)

if __name__ == "__main__":
    solve()

